import{_ as a,c as t,o as i,ag as n}from"./chunks/framework.Vyheyqg9.js";const u=JSON.parse('{"title":"Review changes and prepare a PR","description":"","frontmatter":{},"headers":[],"relativePath":"ai-assisted-engineering/review-pr.md","filePath":"ai-assisted-engineering/review-pr.md"}'),r={name:"ai-assisted-engineering/review-pr.md"};function s(o,e,d,l,c,p){return i(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="_5-review-changes-and-prepare-a-pr" tabindex="-1">Review changes and prepare a PR <a class="header-anchor" href="#_5-review-changes-and-prepare-a-pr" aria-label="Permalink to “Review changes and prepare a PR”">​</a></h1><p>A completed implementation needs an actual reviewable change and an accurate explanation. Generated PR text is useful after you know the final diff and verification results.</p><h2 id="review-the-final-candidate" tabindex="-1"><span class="hub-section-number">1 </span>Review the final candidate <a class="header-anchor" href="#review-the-final-candidate" aria-label="Permalink to “1 Review the final candidate”">​</a></h2><p>Read the task next to the actual diff. For the catalogue feature, check normalization, default versus explicit zero, sort-before-limit, ID ties, invalid options and input ownership. Inspect callers and new files too: a tracked-file diff can omit untracked additions.</p><p>Ask an assistant to identify concrete defects with an input that triggers them. “Could be more robust” is not enough. A useful finding explains the failing behavior, its requirement and where the correction belongs. A review that finds no issue is not proof of correctness or independent human approval.</p><p>Keep these review questions near the code:</p><ul><li>Does the implementation satisfy the agreed behavior and preserve useful existing behavior?</li><li>Do tests fail against a meaningful broken candidate?</li><li>Are credentials, private content or executable model output exposed?</li><li>Did dependencies, configuration or generated files change unnecessarily?</li><li>Are incomplete, cancelled and failed states reported accurately?</li></ul><h2 id="prepare-factual-pr-text" tabindex="-1"><span class="hub-section-number">2 </span>Prepare factual PR text <a class="header-anchor" href="#prepare-factual-pr-text" aria-label="Permalink to “2 Prepare factual PR text”">​</a></h2><p>Lead with the concrete trigger and new behavior. For the worked feature a suitable title is <strong>“Add bounded title search to the notes catalogue.”</strong> A description can say that queries are trimmed and matched case-insensitively, results sort before limiting, and explicit zero is preserved. Add actual build/test outcomes from your candidate, not copied workbench outcomes.</p><p>Do not claim hosted CI passed, a linked issue closed or a reviewer approved unless those events happened. List meaningful limits: this pure helper is not an authenticated endpoint, semantic search engine or deployed UI.</p><h2 id="use-a-local-handoff-record" tabindex="-1"><span class="hub-section-number">3 </span>Use a local handoff record <a class="header-anchor" href="#use-a-local-handoff-record" aria-label="Permalink to “3 Use a local handoff record”">​</a></h2><p>Retain task/acceptance criteria, candidate identity or saved diff, changed files, actual check commands/results, review findings and unresolved gaps. For a real repository include the relevant base revision; do not invent one for an uncommitted standalone exercise.</p><p>This hub forbids remote pushes. Preparing a title/body is local work; creating or updating a remote PR is a separate external action requiring task authorization. The user alone may push. Do not turn a course exercise into automatic publication.</p><p><strong>Your exercise:</strong> review your independent bug fix and feature, correct a concrete finding, then prepare separate local PR summaries. A bug fix and feature can share a study repository without needing one giant PR.</p><p><strong>Done:</strong> a reader can understand the problem, behavior, evidence and limits without reading your chat history. <a href="./reusable-tools.html">Next: reusable workflows and tools</a>. Use <a href="./traceability-and-evaluation.html">traceability depth</a> for larger changes.</p>',15)])])}const f=a(r,[["render",s]]);export{u as __pageData,f as default};
